// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

const withQuery = (path: string, q?: Record<string, unknown>) => {
  const s = new URLSearchParams(Object.entries(q ?? {}).filter(([, v]) => v !== undefined && v !== null)
    .map(([k, v]) => [k, String(v)])).toString();
  return s ? `${path}?${s}` : path;
};

/** Live P&L from the general ledger; salaries appear as a daily run-rate until payroll is posted. */
export interface PnlFlashOut {
  date_from: string;
  date_to: string;
  income: IncomeStreamOut[];
  contra_income: IncomeStreamOut[];
  gross_income: number;
  net_income: number;
  expenses: ExpenseOut[];
  payroll_run_rate: number;
  total_expenses: number;
  net_profit: number;
  cash: CashFlowOut;
  receivables_outstanding: number;
  payables_open: number;
}

export interface IncomeStreamOut {
  account_code: string;
  /** Display name of the income stream (e.g. OPD, Pharmacy, Room charges), or the GL account name */
  stream: string;
  /** Contra income (discounts, refunds) is negative */
  amount: number;
}

export interface ExpenseOut {
  account_code: string;
  category: string;
  amount: number;
}

export interface CashFlowOut {
  collected: number;
  /** Refunds and waiver cash-backs */
  paid_back: number;
  cash_collected: number;
}

export interface PnlTrendDayOut {
  day: string;
  net_income: number;
  /** Without salaries */
  expenses: number;
}

export interface PatientVolumeOut {
  date_from: string;
  date_to: string;
  totals: VolumeTotalsOut;
  per_doctor: DoctorVolumeOut[];
  admissions: number;
}

export interface VolumeTotalsOut {
  /** Tickets sold: the fee settled (paid, panel, credit or waiver), not void or cancelled */
  visited: number;
  /** Tickets issued and never paid (not void or cancelled); unpaid tickets expire (setting unpaid_ticket_expiry_hours) */
  issued_unpaid: number;
  examined: number;
  expired: number;
  refunded: number;
  /** Sold but never examined */
  attrition: number;
}

export interface DoctorVolumeOut {
  /** Null for department-level tickets */
  doctor_id: number | null;
  doctor_name: string | null;
  department_name: string | null;
  visited: number;
  issued_unpaid: number;
  attrition: number;
  examined: number;
  expired: number;
  refunded: number;
}

export interface TrialBalanceRowOut {
  account_code: string;
  name: string;
  type: "Asset" | "Liability" | "Equity" | "Income" | "Expense" | "ContraIncome";
  debit: number;
  credit: number;
  balance: number;
}

/** Live P&L flash (today by default): income streams vs overheads — GET /api/v1/reports/pnl-flash (who may call: holders of finance.dashboard.owner). */
export function pnlFlash(query?: { date_from?: string | null; date_to?: string | null }): Promise<PnlFlashOut> {
  return api<PnlFlashOut>("GET", withQuery(`/reports/pnl-flash`, query), undefined);
}

/** Daily net income vs expenses for a chart (max 92 days) — GET /api/v1/reports/pnl-trend (who may call: holders of finance.dashboard.owner). */
export function pnlTrend(query?: { days?: number }): Promise<PnlTrendDayOut[]> {
  return api<PnlTrendDayOut[]>("GET", withQuery(`/reports/pnl-trend`, query), undefined);
}

/** "Visited" (tickets sold) vs "Examined" per doctor and hospital-wide — GET /api/v1/reports/patient-volume (who may call: holders of finance.dashboard.owner). */
export function patientVolume(query?: { date_from?: string | null; date_to?: string | null }): Promise<PatientVolumeOut> {
  return api<PatientVolumeOut>("GET", withQuery(`/reports/patient-volume`, query), undefined);
}

/** Trial balance — GET /api/v1/finance/gl/trial-balance (who may call: holders of finance.gl.view). */
export function trialBalance(query?: { date_from?: string | null; date_to?: string | null }): Promise<TrialBalanceRowOut[]> {
  return api<TrialBalanceRowOut[]>("GET", withQuery(`/finance/gl/trial-balance`, query), undefined);
}
